import { sql } from "./db.js";
let ready;
export async function ensureSuperLockClaims(env) {
  if (!ready)
    ready = (async () => {
      const db = sql(env);
      // Canonical pick text is generated by the server for props/game lines.
      // Normalize custom text too: books, odds and changing thresholds cannot
      // create a second claim. Sort tokens so team order/word order is immaterial.
      const createKey = db`CREATE OR REPLACE FUNCTION ll_super_lock_key(value TEXT) RETURNS TEXT
      LANGUAGE SQL IMMUTABLE PARALLEL SAFE AS $fn$
      WITH words AS (
        SELECT lower(coalesce(value,'')) AS t
      ), directions AS (
        SELECT regexp_replace(regexp_replace(regexp_replace(t,
          '\\mo(?=[0-9])','over ','g'),'\\mu(?=[0-9])','under ','g'),
          '[0-9]+(?:\\.[0-9]+)?[+]',' over ','g') AS t FROM words
      ), full_stats AS (
        SELECT regexp_replace(regexp_replace(regexp_replace(regexp_replace(t,
          '\\m(?:pass(?:ing)? )?completions?\\M','cmp','g'),
          '\\m(?:pass(?:ing)? )?interceptions?\\M','int','g'),
          '\\mpass(?:ing)? attempts?\\M','att','g'),
          '\\mrush(?:ing)? attempts?\\M','carries','g') AS t FROM directions
      ), aliases AS (
        SELECT regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(t,
          '\\mpassing attempts?\\M','att','g'),
          '\\mpassing completions?\\M','cmp','g'),
          '\\myards?\\M','yds','g'),
          '\\mrushing\\M','rush','g'),
          '\\mpassing\\M','pass','g'),
          '\\mreceiving\\M','rec','g'),
          '\\mtouchdowns?\\M','td','g'),
          '\\mreceptions?\\M','rec','g') AS t FROM full_stats
      ), normalized_stats AS (
        SELECT regexp_replace(regexp_replace(t,
          '\\mtds?\\M','td','g'),
          '\\mrush\\s*(?:[+&]|and)?\\s*rec yds\\M','yds','g') AS t FROM aliases
      ), tokens AS (
        SELECT token FROM normalized_stats, regexp_split_to_table(regexp_replace(regexp_replace(t,'[.''’]','','g'),'[^a-z ]',' ','g'),' +') token
        WHERE token <> '' AND token NOT IN ('fanduel','draftkings','fd','dk','jr','sr','ii','iii','iv','the','and','at','vs','versus')
      ) SELECT coalesce(string_agg(DISTINCT token,' ' ORDER BY token),'') FROM tokens
      $fn$`;
      // The unique index is the arbiter, including simultaneous requests and
      // writes from older browser clients. Existing 2023–25 history is untouched.
      const createIndex = db`CREATE UNIQUE INDEX IF NOT EXISTS picks_super_lock_claim
      ON picks(season,week,ll_super_lock_key(pick_text))
      WHERE bet_type='Super Lock' AND season>=2026`;
      await db.transaction([
        db`SELECT pg_advisory_xact_lock(2147483000, 1)`,
        createKey,
        createIndex,
      ]);
    })().catch((error) => {
      ready = null;
      throw error;
    });
  return ready;
}
export function isSuperLockClaimConflict(error) {
  return (
    error?.code === "23505" && error?.constraint === "picks_super_lock_claim"
  );
}
export const superLockTaken = () =>
  Response.json(
    {
      error: "super-lock-taken",
      detail:
        "That Super Lock is already claimed. The first person to lock it gets it—even at another book or line. Choose a different bet. Your saved picks are unchanged.",
    },
    { status: 409 },
  );
